","const TABLE = "x_1085196_visita_0_visit";
const BASE = `/api/now/table/${TABLE}`;

export interface VisitRecord {
 status?: { value: string; display_value: string };
 visit_date?: { value: string; display_value: string };
 number?: { value: string; display_value: string };
 visitor_name?: { value: string; display_value: string };
 host?: { value: string; display_value: string };
}

function getHeaders(): Record<string, string> {
 return {
 Accept: "application/json",
 "Content-Type": "application/json",
 "X-UserToken": (window as any).g_ck,
 };
}

async function query(params: string): Promise<VisitRecord[]> {
 const res = await fetch(`${BASE}?${params}`, { headers: getHeaders() });
 const data = await res.json();
 return data.result || [];
}

export function fetchTodayVisits(): Promise<VisitRecord[]> {
 const q =
 "visit_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()";
 return query(
 `sysparm_query=${encodeURIComponent(q)}&sysparm_display_value=all&sysparm_fields=status&sysparm_limit=500`
 );
}

export function fetchAllStatuses(): Promise<VisitRecord[]> {
 return query(
 "sysparm_display_value=all&sysparm_fields=status&sysparm_limit=10000"
 );
}

export function fetchWeeklyVisits(): Promise<VisitRecord[]> {
 const q = "visit_date>=javascript:gs.daysAgoStart(7)^ORDERBYvisit_date";
 return query(
 `sysparm_query=${encodeURIComponent(q)}&sysparm_display_value=all&sysparm_fields=visit_date&sysparm_limit=5000`
 );
}
