","import React from "react";
import { VisitRecord } from "../services/visitService";
import { value } from "../utils/fields";

interface Props {
 todayVisits: VisitRecord[];
 loading: boolean;
}

export default function StatCards({ todayVisits, loading }: Props) {
 const total = todayVisits.length;
 const pending = todayVisits.filter((v) => value(v.status) === "pending").length;
 const checkedIn = todayVisits.filter((v) => value(v.status) === "checked_in").length;
 const completed = todayVisits.filter((v) => value(v.status) === "checked_out").length;

 const cards = [
 { label: "Total Visits Today", count: total, accent: "stat-card--primary" },
 { label: "Pending", count: pending, accent: "stat-card--warning" },
 { label: "Currently Checked In", count: checkedIn, accent: "stat-card--positive" },
 { label: "Completed Today", count: completed, accent: "stat-card--neutral" },
 ];

 if (loading) {
 return <div className="stat-cards"><div className="loading">Loading statistics…</div></div>;
 }

 return (
 <div className="stat-cards">
 {cards.map((c) => (
 <div key={c.label} className={`stat-card ${c.accent}`}>
 <div className="stat-card__value">{c.count}</div>
 <div className="stat-card__label">{c.label}</div>
 </div>
 ))}
 </div>
 );
}
","import React from "react";
import { VisitRecord } from "../services/visitService";
import { value } from "../utils/fields";

const STATUSES = [
 { key: "pending", label: "Pending", cls: "status--warning" },
 { key: "approved", label: "Approved", cls: "status--info" },
 { key: "checked_in", label: "Checked In", cls: "status--positive" },
 { key: "checked_out", label: "Checked Out", cls: "status--neutral" },
 { key: "cancelled", label: "Cancelled", cls: "status--critical" },
];

interface Props {
 allStatuses: VisitRecord[];
 loading: boolean;
}

export default function StatusBreakdown({ allStatuses, loading }: Props) {
 const total = allStatuses.length || 1;
 const rows = STATUSES.map((s) => ({
 ...s,
 count: allStatuses.filter((v) => value(v.status) === s.key).length,
 }));

 if (loading) {
 return <div className="card"><div className="card__body loading">Loading…</div></div>;
 }

 return (
 <div className="card">
 <div className="card__header">Status Breakdown</div>
 <div className="card__body">
 {rows.map((r) => (
 <div key={r.key} className="status-row">
 <div className="status-row__info">
 <span className={`status-dot ${r.cls}`} />
 <span className="status-row__label">{r.label}</span>
 </div>
 <div className="status-row__bar-container">
 <div
 className={`status-row__bar ${r.cls}`}
 style={{ width: `${(r.count / total) * 100}%` }}
 />
 </div>
 <span className="status-row__count">{r.count}</span>
 </div>
 ))}
 </div>
 </div>
 );
}
