","import React from "react";
import { VisitRecord } from "../services/visitService";
import { value } from "../utils/fields";

interface Props {
 weeklyVisits: VisitRecord[];
 loading: boolean;
}

function getLast7Days(): { iso: string; label: string }[] {
 const days: { iso: string; label: string }[] = [];
 for (let i = 6; i >= 0; i--) {
 const d = new Date();
 d.setDate(d.getDate() - i);
 days.push({
 iso: d.toISOString().split("T")[0],
 label: d.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" }),
 });
 }
 return days;
}

export default function WeeklyTrend({ weeklyVisits, loading }: Props) {
 const days = getLast7Days();
 const counts = days.map((day) => ({
 ...day,
 count: weeklyVisits.filter((v) => value(v.visit_date).startsWith(day.iso)).length,
 }));
 const max = Math.max(...counts.map((c) => c.count), 1);

 if (loading) {
 return <div className="card"><div className="card__body loading">Loading…</div></div>;
 }

 return (
 <div className="card">
 <div className="card__header">Weekly Trend (Last 7 Days)</div>
 <div className="card__body">
 <div className="weekly-chart">
 {counts.map((day) => (
 <div key={day.iso} className="weekly-chart__day">
 <div className="weekly-chart__bar-wrapper">
 <div
 className="weekly-chart__bar"
 style={{ height: `${(day.count / max) * 100}%` }}
 />
 </div>
 <div className="weekly-chart__count">{day.count}</div>
 <div className="weekly-chart__label">{day.label}</div>
 </div>
 ))}
 </div>
 </div>
 </div>
 );
}
","/* ── ROOT ALIASES ─────────────────────────────────────────── */
:root {
 --dash-surface: rgb(var(--now-color_background--primary, 255, 255, 255));
 --dash-surface-alt: rgb(var(--now-color_background--secondary, 245, 246, 247));
 --dash-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --dash-text-muted: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --dash-border: rgb(var(--now-container-card--border-color, 207, 213, 215));
 --dash-radius: var(--now-container-card--border-radius, 8px);
 --dash-font: var(--now-font-family, system-ui, sans-serif);
}

/* ── DASHBOARD LAYOUT ────────────────────────────────────── */
.dashboard {
 max-width: 1200px;
 margin: 0 auto;
 padding: var(--now-static-space--xl, 1.5rem);
 font-family: var(--dash-font);
 color: var(--dash-text);
 background-color: var(--dash-surface-alt);
 min-height: 100vh;
}

.dashboard__header {
 margin: 0 0 var(--now-static-space--xl, 1.5rem) 0;
}

.dashboard__title {
 margin: 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 600;
 color: var(--dash-text);
 line-height: var(--now-static-line-height, 1.25);
}

.dashboard__subtitle {
 margin: var(--now-static-space--xs, 0.25rem) 0 0 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--dash-text-muted);
}

.dashboard__grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--now-static-space--xl, 1.5rem);
 margin-bottom: var(--now-static-space--xl, 1.5rem);
}

/* ── STAT CARDS ──────────────────────────────────────────── */
.stat-cards {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: var(--now-static-space--lg, 1rem);
 margin-bottom: var(--now-static-space--xl, 1.5rem);
}

.stat-card {
 background-color: var(--dash-surface);
 border: 1px solid var(--dash-border);
 border-radius: var(--dash-radius);
 padding: var(--now-static-space--xl, 1.5rem);
 box-shadow: var(--now-static-drop-shadow--sm);
 border-top: 4px solid var(--dash-border);
 text-align: center;
}

.stat-card--primary {
 border-top-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}
.stat-card--warning {
 border-top-color: rgb(var(--now-indicator--primary_warning--background-color, 255, 186, 0));
}
.stat-card--positive {
 border-top-color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
}
.stat-card--neutral {
 border-top-color: rgb(var(--now-color_text--secondary, 75, 85, 89));
}

.stat-card__value {
 font-size: 2.5rem;
 font-weight: 700;
 line-height: 1;
 margin-bottom: var(--now-static-space--sm, 0.5rem);
 color: var(--dash-text);
}

.stat-card__label {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--dash-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.05em;
 font-weight: 600;
}

/* ── CARD (generic) ──────────────────────────────────────── */
.card {
 background-color: var(--dash-surface);
 border: 1px solid var(--dash-border);
 border-radius: var(--dash-radius);
 box-shadow: var(--now-static-drop-shadow--sm);
 display: flex;
 flex-direction: column;
 overflow: hidden;
}

.card__header {
 padding: var(--now-static-space--lg, 1rem);
 border-bottom: 1px solid var(--dash-border);
 font-weight: 600;
 font-size: var(--now-static-font-size--md, 1rem);
 color: var(--dash-text);
}

.card__body {
 padding: var(--now-static-space--lg, 1rem);
 flex: 1;
}

.card__body--no-padding {
 padding: 0;
}

/* ── STATUS BREAKDOWN ────────────────────────────────────── */
.status-row {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--md, 0.75rem);
 padding: var(--now-static-space--sm, 0.5rem) 0;
}

.status-row + .status-row {
 border-top: 1px solid var(--dash-surface-alt);
}

.status-row__info {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--sm, 0.5rem);
 min-width: 110px;
}

.status-dot {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 flex-shrink: 0;
}

.status-dot.status--warning {
 background-color: rgb(var(--now-indicator--primary_warning--background-color, 255, 186, 0));
}
.status-dot.status--info {
 background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}
.status-dot.status--positive {
 background-color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
}
.status-dot.status--neutral {
 background-color: rgb(var(--now-color_text--secondary, 75, 85, 89));
}
.status-dot.status--critical {
 background-color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
}

.status-row__label {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--dash-text);
 font-weight: 500;
}

.status-row__bar-container {
 flex: 1;
 height: 8px;
 background-color: var(--dash-surface-alt);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 overflow: hidden;
}

.status-row__bar {
 height: 100%;
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 min-width: 2px;
 transition: width 300ms ease;
}

.status-row__bar.status--warning {
 background-color: rgb(var(--now-indicator--primary_warning--background-color, 255, 186, 0));
}
.status-row__bar.status--info {
 background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}
.status-row__bar.status--positive {
 background-color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
}
.status-row__bar.status--neutral {
 background-color: rgb(var(--now-color_text--secondary, 75, 85, 89));
}
.status-row__bar.status--critical {
 background-color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
}

.status-row__count {
 font-weight: 600;
 min-width: 2rem;
 text-align: right;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--dash-text);
}

/* ── WEEKLY TREND ────────────────────────────────────────── */
.weekly-chart {
 display: flex;
 align-items: flex-end;
 justify-content: space-between;
 gap: var(--now-static-space--sm, 0.5rem);
 height: 180px;
 padding-top: var(--now-static-space--lg, 1rem);
}

.weekly-chart__day {
 flex: 1;
 display: flex;
 flex-direction: column;
 align-items: center;
 height: 100%;
}

.weekly-chart__bar-wrapper {
 flex: 1;
 width: 100%;
 display: flex;
 align-items: flex-end;
 justify-content: center;
}

.weekly-chart__bar {
 width: 60%;
 min-height: 4px;
 background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 border-radius: var(--now-static-border-radius--sm, 0.125rem)
 var(--now-static-border-radius--sm, 0.125rem) 0 0;
 transition: height 300ms ease;
}

.weekly-chart__count {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 600;
 color: var(--dash-text);
 padding: var(--now-static-space--xxs, 0.125rem) 0;
}

.weekly-chart__label {
 font-size: 0.625rem;
 color: var(--dash-text-muted);
 text-align: center;
 white-space: nowrap;
}

/* ── LOADING STATE ───────────────────────────────────────── */
.loading {
 display: flex;
 align-items: center;
 justify-content: center;
 padding: var(--now-static-space--xxl, 2rem);
 color: var(--dash-text-muted);
 font-style: italic;
}

/* ── RESPONSIVE ──────────────────────────────────────────── */
@media (max-width: 900px) {
 .stat-cards {
 grid-template-columns: repeat(2, 1fr);
 }
 .dashboard__grid {
 grid-template-columns: 1fr;
 }
}

@media (max-width: 600px) {
 .stat-cards {
 grid-template-columns: 1fr;
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
