","import React, { useState, useEffect } from "react";
import {
 fetchTodayVisits,
 fetchAllStatuses,
 fetchWeeklyVisits,
 VisitRecord,
} from "./services/visitService";
import StatCards from "./components/StatCards";
import StatusBreakdown from "./components/StatusBreakdown";
import RecentVisits from "./components/RecentVisits";
import WeeklyTrend from "./components/WeeklyTrend";
import "./dashboard.css";

export default function App() {
 const [todayVisits, setTodayVisits] = useState<VisitRecord[]>([]);
 const [allStatuses, setAllStatuses] = useState<VisitRecord[]>([]);
 const [weeklyVisits, setWeeklyVisits] = useState<VisitRecord[]>([]);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 Promise.all([fetchTodayVisits(), fetchAllStatuses(), fetchWeeklyVisits()])
 .then(([today, statuses, weekly]) => {
 setTodayVisits(today);
 setAllStatuses(statuses);
 setWeeklyVisits(weekly);
 })
 .finally(() => setLoading(false));
 }, []);

 return (
 <div className="dashboard">
 <header className="dashboard__header">
 <h1 className="dashboard__title">Visit Tracking Dashboard</h1>
 <p className="dashboard__subtitle">
 Real-time analytics for the Visitation Application
 </p>
 </header>

 <StatCards todayVisits={todayVisits} loading={loading} />

 <div className="dashboard__grid">
 <StatusBreakdown allStatuses={allStatuses} loading={loading} />
 <WeeklyTrend weeklyVisits={weeklyVisits} loading={loading} />
 </div>

 <RecentVisits />
 </div>
 );
}
